package com.paymesh.backend.chat.conversations;

import com.fasterxml.jackson.databind.*;
import com.paymesh.backend.chat.*;
import com.paymesh.backend.security.accounts.*;
import java.time.*;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import static com.paymesh.backend.chat.conversations.ConversationDtos.*;

/** Every operation is short and serialized with the existing account administration lock. Never HTTP here. */
@Service
@Transactional(propagation=Propagation.REQUIRES_NEW,isolation=Isolation.READ_COMMITTED,timeout=8)
public class ConversationTransactions {
 private final AuthStore db;private final ChatEvidenceBuilder access;private final DashboardAnalytics analytics;private final ObjectMapper json;
 public ConversationTransactions(AuthStore db,ChatEvidenceBuilder access,DashboardAnalytics analytics,ObjectMapper json){this.db=db;this.access=access;this.analytics=analytics;this.json=json.copy().enable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES);}
 private String t(String n){return db.table(n);}
 private ChatDtos.Input input(ChatDtos.Context c){return ChatDtos.validate(new ChatDtos.Input("Conversation authorization",List.of(),c));}
 private ChatEvidenceBuilder.Selection actor(String portal){if(!Set.of("merchant","admin").contains(portal))throw ChatDtos.invalid();return access.withinTransaction(portal,input(null));}
 private ChatDtos.Context context(Object value){try{return json.readValue(value.toString(),ChatDtos.Context.class);}catch(Exception e){throw new ChatFailure(503,"CONVERSATION_UNAVAILABLE","Stored conversation format is unavailable.");}}
 private String encode(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException("Conversation serialization unavailable");}}
 public static Map<String,Object> contextMap(ChatDtos.Context c){Map<String,Object> m=new LinkedHashMap<>();if(c.paymentId()!=null)m.put("paymentId",c.paymentId());if(c.merchantId()!=null)m.put("merchantId",c.merchantId());if(c.statistics()!=null){Map<String,Object>s=new LinkedHashMap<>();if(c.statistics().from()!=null)s.put("from",c.statistics().from());if(c.statistics().to()!=null)s.put("to",c.statistics().to());if(c.statistics().currency()!=null)s.put("currency",c.statistics().currency());m.put("statistics",s);}return m;}
 private ChatDtos.Context normalize(String portal,ChatDtos.Context c){if(c==null)c=new ChatDtos.Context(null,null,null,null);ChatDtos.validate(input(c));if(c.paymentLinkId()!=null||portal.equals("merchant")&&c.merchantId()!=null||c.paymentId()!=null&&c.statistics()!=null)throw ChatDtos.invalid();
  ChatDtos.Statistics stats=c.paymentId()!=null?null:c.statistics()==null?new ChatDtos.Statistics(null,null,null):c.statistics();
  if(stats!=null){Map<String,String> f=new HashMap<>();if(stats.from()!=null)f.put("from",stats.from());if(stats.to()!=null)f.put("to",stats.to());if(stats.currency()!=null)f.put("currency",stats.currency());analytics.range(f,portal.equals("admin"));stats=new ChatDtos.Statistics(stats.from()==null?null:Instant.parse(stats.from()).toString(),stats.to()==null?null:Instant.parse(stats.to()).toString(),stats.currency());}
  return new ChatDtos.Context(c.paymentId(),null,c.merchantId(),stats);
 }
 private Map<String,Object> owned(String portal,UUID id,boolean lock){var who=actor(portal);var rows=db.jdbc.queryForList("SELECT * FROM "+t("ai_conversations")+" WHERE conversation_id=? AND owner_id=? AND portal_role=? AND expires_at>clock_timestamp()"+(lock?" FOR UPDATE":""),id,who.actor(),portal.toUpperCase(Locale.ROOT));if(rows.isEmpty())throw missing();var row=rows.getFirst();authorize(portal,row);return row;}
 private void authorize(String portal,Map<String,Object> row){var current=access.withinTransaction(portal,input(context(row.get("context"))));String scope=(String)row.get("scope_merchant_id");if(!current.actor().equals(row.get("owner_id"))||!Objects.equals(scope,current.merchantId().isEmpty()?null:current.merchantId()))throw missing();}
 private Map<String,Object> summary(String portal,Map<String,Object> row){Map<String,Object> out=new LinkedHashMap<>();out.put("conversationId",row.get("conversation_id").toString());out.put("portalRole",row.get("portal_role"));out.put("contextType",row.get("context_type"));out.put("context",contextMap(context(row.get("context"))));out.put("title",row.get("title"));out.put("version",row.get("version"));out.put("turnCount",row.get("turn_count"));for(String key:List.of("created_at","updated_at","expires_at"))out.put(switch(key){case "created_at"->"createdAt";case "updated_at"->"updatedAt";default->"expiresAt";},AuthStore.instant(row,key).toString());
  out.put("merchantId",row.get("scope_merchant_id"));out.put("payment",null);out.put("merchant",null);
  if(row.get("payment_id")!=null){var p=db.jdbc.queryForMap("SELECT payment_id,merchant_id,amount,currency,payment_method,status FROM "+t("payments")+" WHERE payment_id=? AND merchant_id=?",row.get("payment_id"),row.get("scope_merchant_id"));out.put("payment",Map.of("paymentId",p.get("payment_id").toString(),"merchantId",p.get("merchant_id"),"amount",((BigDecimal)p.get("amount")).setScale(2).toPlainString(),"currency",p.get("currency"),"paymentMethod",p.get("payment_method"),"status",p.get("status")));}
  if(row.get("scope_merchant_id")!=null){var list=db.jdbc.queryForList("SELECT m.merchant_id AS \"merchantId\",r.business_name AS \"businessName\",a.status FROM "+t("merchants")+" m JOIN "+t("merchant_administration")+" a ON a.merchant_id=m.merchant_id LEFT JOIN "+t("merchant_registrations")+" r ON r.merchant_id=m.merchant_id WHERE m.merchant_id=?",row.get("scope_merchant_id"));if(list.size()!=1)throw missing();out.put("merchant",list.getFirst());}
  var pending=db.jdbc.queryForList("SELECT request_id,expected_version,status,lease_until FROM "+t("ai_conversation_requests")+" WHERE conversation_id=? AND status='IN_PROGRESS'",row.get("conversation_id"));out.put("activeRequest",pending.isEmpty()?null:requestMeta(pending.getFirst()));return out;
 }
 private Map<String,Object> requestMeta(Map<String,Object> row){String status=row.get("status").toString();if(status.equals("IN_PROGRESS")&&!AuthStore.instant(row,"lease_until").isAfter(Instant.now()))status="UNCERTAIN";return Map.of("requestId",row.get("request_id").toString(),"expectedVersion",row.get("expected_version"),"status",status);}
 public Map<String,Object> create(String portal,Create in){var who=actor(portal);UUID requestId=ChatDtos.uuid(in.requestId());ChatDtos.Context ctx=normalize(portal,in.context());var scope=access.withinTransaction(portal,input(ctx));String role=portal.toUpperCase(Locale.ROOT),kind=ctx.paymentId()!=null?"PAYMENT":scope.merchantId().isEmpty()?"PLATFORM":"MERCHANT";String title=in.title()==null?kind.substring(0,1)+kind.substring(1).toLowerCase(Locale.ROOT)+" conversation":ConversationDtos.title(in.title());String encoded=encode(contextMap(ctx)),fingerprint=AuthStore.digest(encoded+"\n"+title);
  var prior=db.jdbc.queryForList("SELECT * FROM "+t("ai_conversation_creations")+" WHERE owner_id=? AND portal_role=? AND request_id=?",who.actor(),role,requestId);
  if(!prior.isEmpty()){var p=prior.getFirst();if(!AuthStore.equal(fingerprint,p.get("fingerprint").toString()))throw conflict();if(p.get("conversation_id")==null)throw new ChatFailure(410,"CONVERSATION_GONE","The original conversation was deleted or expired; use a new creation request identifier deliberately.");return Map.of("conversation",summary(portal,owned(portal,(UUID)p.get("conversation_id"),false)),"replay",true);}
  long count=db.jdbc.queryForObject("SELECT count(*) FROM "+t("ai_conversations")+" WHERE owner_id=? AND portal_role=?",Long.class,who.actor(),role),journal=db.jdbc.queryForObject("SELECT count(*) FROM "+t("ai_conversation_creations")+" WHERE owner_id=? AND portal_role=?",Long.class,who.actor(),role);
  if(count>=50||journal>=200)throw new ChatFailure(429,"CONVERSATION_LIMIT","Conversation storage limit reached; delete content or wait for bounded retention cleanup.");
  UUID id=UUID.randomUUID();db.jdbc.update("INSERT INTO "+t("ai_conversations")+"(conversation_id,owner_id,portal_role,context_type,scope_merchant_id,payment_id,context,title) VALUES (?,?,?,?,?,?,?::jsonb,?)",id,who.actor(),role,kind,scope.merchantId().isEmpty()?null:scope.merchantId(),ctx.paymentId()==null?null:ChatDtos.uuid(ctx.paymentId()),encoded,title);
  db.jdbc.update("INSERT INTO "+t("ai_conversation_creations")+"(owner_id,portal_role,request_id,fingerprint,conversation_id) VALUES (?,?,?,?,?)",who.actor(),role,requestId,fingerprint,id);return Map.of("conversation",summary(portal,owned(portal,id,false)),"replay",false);
 }
 public Map<String,Object> creation(String portal,UUID requestId){var who=actor(portal);var rows=db.jdbc.queryForList("SELECT conversation_id FROM "+t("ai_conversation_creations")+" WHERE owner_id=? AND portal_role=? AND request_id=?",who.actor(),portal.toUpperCase(Locale.ROOT),requestId);if(rows.isEmpty())throw missing();if(rows.getFirst().get("conversation_id")==null)throw new ChatFailure(410,"CONVERSATION_GONE","Original conversation is deleted or expired.");return Map.of("conversation",summary(portal,owned(portal,(UUID)rows.getFirst().get("conversation_id"),false)),"replay",true);}
 public Map<String,Object> list(String portal,int page,int size,String search,UUID exactPayment){var who=actor(portal);if(page<0||page>10000||size<1||size>10||search.length()>120||search.chars().anyMatch(c->c<32||c==127))throw ChatDtos.invalid();String literal="%"+search.replace("!","!!").replace("%","!%").replace("_","!_")+"%";var rows=db.jdbc.queryForList("SELECT * FROM "+t("ai_conversations")+" WHERE owner_id=? AND portal_role=? AND expires_at>clock_timestamp() AND title ILIKE ? ESCAPE '!' ORDER BY updated_at DESC,conversation_id DESC LIMIT 50",who.actor(),portal.toUpperCase(Locale.ROOT),literal);List<Map<String,Object>> visible=new ArrayList<>();
  for(var row:rows){try{var c=context(row.get("context"));if(exactPayment!=null&&(!exactPayment.toString().equals(c.paymentId())||c.merchantId()!=null||c.statistics()!=null))continue;authorize(portal,row);visible.add(row);}catch(ChatFailure e){if(e.status()!=403&&e.status()!=404)throw e;}catch(com.paymesh.backend.security.accounts.AccountAccessDeniedException|com.paymesh.backend.exception.PaymentNotFoundException e){/* No title/content from an inaccessible saved scope. */}}
  actor(portal);int start=(int)Math.min((long)page*size,visible.size()),end=Math.min(start+size,visible.size());return Map.of("items",visible.subList(start,end).stream().map(r->summary(portal,r)).toList(),"page",page,"size",size,"total",visible.size());
 }
 public Map<String,Object> detail(String portal,UUID id){return Map.of("conversation",summary(portal,owned(portal,id,false)));}
 public Map<String,Object> messages(String portal,UUID id,int page,int size){var row=owned(portal,id,false);if(page<0||page>10000||size<1||size>10)throw ChatDtos.invalid();var turns=readTurns(id,size,page*size);Collections.reverse(turns);return Map.of("conversation",summary(portal,row),"turns",turns,"page",page,"size",size,"total",row.get("turn_count"));}
 private List<Turn> readTurns(UUID id,int limit,int offset){return new ArrayList<>(db.jdbc.query("SELECT u.request_id,u.content,a.public_response::text AS response,a.ordinal,a.created_at FROM "+t("ai_conversation_messages")+" u JOIN "+t("ai_conversation_messages")+" a ON a.conversation_id=u.conversation_id AND a.request_id=u.request_id AND a.message_role='assistant' WHERE u.conversation_id=? AND u.message_role='user' ORDER BY a.ordinal DESC LIMIT ? OFFSET ?",(rs,n)->{try{return new Turn(rs.getObject("request_id",UUID.class).toString(),rs.getInt("ordinal")/2,rs.getString("content"),json.readValue(rs.getString("response"),ChatDtos.Response.class),rs.getTimestamp("created_at").toInstant().toString());}catch(Exception e){throw new IllegalStateException("Saved response format unavailable");}},id,limit,offset));}
 public Map<String,Object> rename(String portal,UUID id,Rename in){var row=owned(portal,id,true);checkVersion(row,ConversationDtos.version(in.expectedVersion()));db.jdbc.update("UPDATE "+t("ai_conversations")+" SET title=?,version=version+1,updated_at=clock_timestamp() WHERE conversation_id=?",ConversationDtos.title(in.title()),id);return detail(portal,id);}
 public Map<String,Object> delete(String portal,UUID id,long version){var row=owned(portal,id,true);checkVersion(row,version);db.jdbc.update("DELETE FROM "+t("ai_conversations")+" WHERE conversation_id=?",id);return Map.of("deleted",true);}
 private void checkVersion(Map<String,Object> row,long version){if(((Number)row.get("version")).longValue()!=version)throw conflict();}
 private Map<String,Object> requestRow(UUID id,UUID rid){var rows=db.jdbc.queryForList("SELECT * FROM "+t("ai_conversation_requests")+" WHERE conversation_id=? AND request_id=?",id,rid);if(rows.isEmpty())throw missing();return rows.getFirst();}
 private Map<String,Object> result(String portal,Map<String,Object> conversation,Map<String,Object> req){Map<String,Object> out=new LinkedHashMap<>(requestMeta(req));out.put("conversation",summary(portal,conversation));out.put("errorCode",req.get("error_code"));out.put("turn",null);if(req.get("status").equals("COMPLETED")){var turns=readTurns((UUID)conversation.get("conversation_id"),50,0);out.put("turn",turns.stream().filter(t->t.requestId().equals(req.get("request_id").toString())).findFirst().orElseThrow(()->new IllegalStateException("Incomplete saved pair")));}return out;}
 public Map<String,Object> requestStatus(String portal,UUID id,UUID rid){var row=owned(portal,id,false);return result(portal,row,requestRow(id,rid));}
 public Work begin(String portal,UUID id,Send in){ChatDtos.validate(new ChatDtos.Input(in.question(),List.of(),null));UUID rid=ChatDtos.uuid(in.requestId());long version=ConversationDtos.version(in.expectedVersion());var row=owned(portal,id,true);String digest=AuthStore.digest(in.question());var requests=db.jdbc.queryForList("SELECT * FROM "+t("ai_conversation_requests")+" WHERE conversation_id=? AND request_id=?",id,rid);
  if(!requests.isEmpty()){var r=requests.getFirst();if(!AuthStore.equal(digest,r.get("question_digest").toString())||((Number)r.get("expected_version")).longValue()!=version)throw conflict();if(r.get("status").equals("COMPLETED")||r.get("status").equals("IN_PROGRESS")&&AuthStore.instant(r,"lease_until").isAfter(Instant.now()))return new Work(id,rid,null,version,null,null,null,0,null,result(portal,row,r));if(((Number)r.get("attempts")).intValue()>=3)throw new ChatFailure(409,"REQUEST_RETRY_LIMIT","Reconcile or delete this conversation; request retry limit reached.");}
  checkVersion(row,version);if(((Number)row.get("turn_count")).intValue()>=50||((Number)row.get("content_bytes")).intValue()>=1048576)throw new ChatFailure(422,"CONVERSATION_LIMIT","Conversation storage limit reached. Start a new conversation.");
  long inflight=db.jdbc.queryForObject("SELECT count(*) FROM "+t("ai_conversation_requests")+" WHERE conversation_id=? AND status='IN_PROGRESS' AND request_id<>?",Long.class,id,rid);if(inflight>0)throw conflict();UUID nonce=UUID.randomUUID();
  if(requests.isEmpty()){if(db.jdbc.queryForObject("SELECT count(*) FROM "+t("ai_conversation_requests")+" WHERE conversation_id=?",Integer.class,id)>=100)throw new ChatFailure(422,"CONVERSATION_LIMIT","Conversation request limit reached.");db.jdbc.update("INSERT INTO "+t("ai_conversation_requests")+"(conversation_id,request_id,question_digest,expected_version,status,worker_nonce,lease_until) VALUES (?,?,?,?,'IN_PROGRESS',?,clock_timestamp()+interval '120 seconds')",id,rid,digest,version,nonce);}else db.jdbc.update("UPDATE "+t("ai_conversation_requests")+" SET status='IN_PROGRESS',worker_nonce=?,attempts=attempts+1,error_code=NULL,updated_at=clock_timestamp(),lease_until=clock_timestamp()+interval '120 seconds' WHERE conversation_id=? AND request_id=?",nonce,id,rid);
  List<ChatDtos.Message> history=new ArrayList<>();int chars=0;for(var turn:readTurns(id,4,0)){var q=turn.question();var a=turn.response().answer();int n=q.codePointCount(0,q.length())+a.codePointCount(0,a.length());if(q.codePointCount(0,q.length())>1000||a.codePointCount(0,a.length())>1000||chars+n>6000)break;try{ChatDtos.validate(new ChatDtos.Input(q,List.of(new ChatDtos.Message("assistant",a)),null));}catch(ChatFailure e){break;}history.add(0,new ChatDtos.Message("assistant",a));history.add(0,new ChatDtos.Message("user",q));chars+=n;}
  var input=ChatDtos.validate(new ChatDtos.Input(in.question(),List.copyOf(history),context(row.get("context"))));var authorized=access.withinTransaction(portal,input);return new Work(id,rid,nonce,version,in.question(),input,authorized.actor(),authorized.version(),authorized.merchantId(),null);
 }
 public Map<String,Object> finish(String portal,Work work,ChatDtos.Response response){var row=owned(portal,work.conversationId(),true);var req=requestRow(work.conversationId(),work.requestId());if(!req.get("status").equals("IN_PROGRESS")||!req.get("worker_nonce").equals(work.nonce()))throw conflict();checkVersion(row,work.expectedVersion());String encoded=encode(response);int bytes=work.question().getBytes(StandardCharsets.UTF_8).length+encoded.getBytes(StandardCharsets.UTF_8).length;if(encoded.getBytes(StandardCharsets.UTF_8).length>60000||((Number)row.get("content_bytes")).intValue()+bytes>1048576)throw new ChatFailure(422,"CONVERSATION_LIMIT","Validated response exceeds conversation storage limits.");int ordinal=((Number)row.get("turn_count")).intValue()*2;
  db.jdbc.update("INSERT INTO "+t("ai_conversation_messages")+"(conversation_id,request_id,ordinal,message_role,content) VALUES (?,?,?,'user',?)",work.conversationId(),work.requestId(),ordinal+1,work.question());db.jdbc.update("INSERT INTO "+t("ai_conversation_messages")+"(conversation_id,request_id,ordinal,message_role,public_response) VALUES (?,?,?,'assistant',?::jsonb)",work.conversationId(),work.requestId(),ordinal+2,encoded);
  db.jdbc.update("UPDATE "+t("ai_conversation_requests")+" SET status='COMPLETED',updated_at=clock_timestamp(),error_code=NULL WHERE conversation_id=? AND request_id=? AND worker_nonce=?",work.conversationId(),work.requestId(),work.nonce());db.jdbc.update("UPDATE "+t("ai_conversations")+" SET version=version+1,turn_count=turn_count+1,content_bytes=content_bytes+?,updated_at=clock_timestamp() WHERE conversation_id=?",bytes,work.conversationId());return requestStatus(portal,work.conversationId(),work.requestId());
 }
 public void fail(String portal,Work work,String code){owned(portal,work.conversationId(),true);db.jdbc.update("UPDATE "+t("ai_conversation_requests")+" SET status='FAILED',error_code=?,updated_at=clock_timestamp() WHERE conversation_id=? AND request_id=? AND worker_nonce=? AND status='IN_PROGRESS'",Set.of("AI_CAPACITY","AI_UNAVAILABLE","AI_TIMEOUT","INVALID_AI_RESPONSE","CONVERSATION_CONFLICT","CONVERSATION_LIMIT","EVIDENCE_TOO_LARGE","UNSUPPORTED_EVIDENCE").contains(code)?code:"REQUEST_FAILED",work.conversationId(),work.requestId(),work.nonce());}
}
